-- Experiment-only schema; Better Auth's tables are generated by pinned 1.7.6.
CREATE SCHEMA auth_binding;
ALTER TABLE ba_fixture.session ADD UNIQUE(id,"userId");
CREATE TABLE auth_binding.policy (
  account_id text PRIMARY KEY REFERENCES ba_fixture."user"(id),
  remote_account_id uuid NOT NULL UNIQUE,
  state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','suspended')),
  epoch bigint NOT NULL DEFAULT 1 CHECK(epoch>0)
);
CREATE TABLE auth_binding.session_class (
  session_id text PRIMARY KEY,
  account_id text NOT NULL REFERENCES auth_binding.policy,
  kind text NOT NULL CHECK(kind IN ('web','mobile','desktop','bootstrap')),
  UNIQUE(session_id,account_id,kind),
  FOREIGN KEY(session_id,account_id) REFERENCES ba_fixture.session(id,"userId") ON DELETE CASCADE
);
CREATE FUNCTION auth_binding.immutable_class() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'immutable server session class'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER immutable_class BEFORE UPDATE ON auth_binding.session_class FOR EACH ROW EXECUTE FUNCTION auth_binding.immutable_class();
CREATE TABLE auth_binding.enrollment (
  id uuid PRIMARY KEY, host_id uuid NOT NULL,
  initial_commitment bytea NOT NULL CHECK(octet_length(initial_commitment)=32),
  signed_key jsonb NOT NULL,
  fingerprint bytea CHECK(fingerprint IS NULL OR octet_length(fingerprint)=32),
  device_hash bytea NOT NULL UNIQUE CHECK(octet_length(device_hash)=32),
  bootstrap_id uuid NOT NULL UNIQUE, operation_id uuid NOT NULL UNIQUE,
  account_id text REFERENCES auth_binding.policy, approved boolean NOT NULL DEFAULT false,
  epoch bigint, revoked boolean NOT NULL DEFAULT false,
  expires_at timestamptz NOT NULL, nonce bytea NOT NULL CHECK(octet_length(nonce)=32),
  CHECK ((approved AND account_id IS NOT NULL AND epoch IS NOT NULL AND fingerprint IS NOT NULL) OR (NOT approved AND account_id IS NULL AND epoch IS NULL AND fingerprint IS NULL)),
  UNIQUE(id,account_id,bootstrap_id)
);
CREATE FUNCTION auth_binding.immutable_enrollment() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (NEW.id,NEW.host_id,NEW.initial_commitment,NEW.signed_key,NEW.device_hash,NEW.bootstrap_id,NEW.operation_id,NEW.expires_at,NEW.nonce)
 IS DISTINCT FROM (OLD.id,OLD.host_id,OLD.initial_commitment,OLD.signed_key,OLD.device_hash,OLD.bootstrap_id,OLD.operation_id,OLD.expires_at,OLD.nonce)
 OR (OLD.account_id IS NOT NULL AND (NEW.account_id,NEW.epoch) IS DISTINCT FROM (OLD.account_id,OLD.epoch))
 OR (OLD.fingerprint IS NOT NULL AND NEW.fingerprint IS DISTINCT FROM OLD.fingerprint)
 OR (OLD.approved AND NOT NEW.approved) OR (OLD.revoked AND NOT NEW.revoked)
 THEN RAISE EXCEPTION 'immutable enrollment binding'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable_enrollment BEFORE UPDATE ON auth_binding.enrollment FOR EACH ROW EXECUTE FUNCTION auth_binding.immutable_enrollment();
CREATE TABLE auth_binding.bootstrap (
  id uuid PRIMARY KEY, enrollment_id uuid NOT NULL UNIQUE,
  account_id text NOT NULL, session_id text NOT NULL UNIQUE,
  kind text NOT NULL DEFAULT 'bootstrap' CHECK(kind='bootstrap'),
  consumed boolean NOT NULL DEFAULT false,
  FOREIGN KEY(enrollment_id,account_id,id) REFERENCES auth_binding.enrollment(id,account_id,bootstrap_id),
  FOREIGN KEY(session_id,account_id,kind) REFERENCES auth_binding.session_class(session_id,account_id,kind) ON DELETE CASCADE
);
CREATE FUNCTION auth_binding.immutable_bootstrap() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (NEW.id,NEW.enrollment_id,NEW.account_id,NEW.session_id,NEW.kind) IS DISTINCT FROM
    (OLD.id,OLD.enrollment_id,OLD.account_id,OLD.session_id,OLD.kind) OR (OLD.consumed AND NOT NEW.consumed)
 THEN RAISE EXCEPTION 'immutable bootstrap mapping'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable_bootstrap BEFORE UPDATE ON auth_binding.bootstrap FOR EACH ROW EXECUTE FUNCTION auth_binding.immutable_bootstrap();
CREATE TABLE auth_binding.host_authorization (
  id uuid PRIMARY KEY, enrollment_id uuid NOT NULL UNIQUE REFERENCES auth_binding.enrollment,
  account_id text NOT NULL REFERENCES auth_binding.policy, epoch bigint NOT NULL,
  revoked boolean NOT NULL DEFAULT false
);
CREATE TABLE auth_binding.consumer (
  id uuid PRIMARY KEY, account_id text NOT NULL REFERENCES auth_binding.policy,
  kind text NOT NULL CHECK(kind IN ('web','mobile','desktop')),
  web_session_id text UNIQUE, mobile_session_id text UNIQUE, desktop_session_id text UNIQUE,
  web_kind text GENERATED ALWAYS AS ('web'::text) STORED,
  mobile_kind text GENERATED ALWAYS AS ('mobile'::text) STORED,
  desktop_kind text GENERATED ALWAYS AS ('desktop'::text) STORED,
  epoch bigint NOT NULL,
  CHECK ((kind='web' AND web_session_id IS NOT NULL AND mobile_session_id IS NULL AND desktop_session_id IS NULL)
      OR (kind='mobile' AND mobile_session_id IS NOT NULL AND web_session_id IS NULL AND desktop_session_id IS NULL)
      OR (kind='desktop' AND desktop_session_id IS NOT NULL AND web_session_id IS NULL AND mobile_session_id IS NULL)),
  FOREIGN KEY(web_session_id,account_id,web_kind) REFERENCES auth_binding.session_class(session_id,account_id,kind) ON DELETE CASCADE,
  FOREIGN KEY(mobile_session_id,account_id,mobile_kind) REFERENCES auth_binding.session_class(session_id,account_id,kind) ON DELETE CASCADE,
  FOREIGN KEY(desktop_session_id,account_id,desktop_kind) REFERENCES auth_binding.session_class(session_id,account_id,kind) ON DELETE CASCADE
);
CREATE TRIGGER immutable_consumer BEFORE UPDATE ON auth_binding.consumer FOR EACH ROW EXECUTE FUNCTION auth_binding.immutable_class();
CREATE TABLE auth_binding.window_key (
 id uuid PRIMARY KEY, consumer_id uuid NOT NULL REFERENCES auth_binding.consumer ON DELETE CASCADE,
 fingerprint bytea NOT NULL UNIQUE CHECK(octet_length(fingerprint)=32), retired boolean NOT NULL DEFAULT false
);
CREATE FUNCTION auth_binding.window_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
   IF (NEW.id,NEW.consumer_id,NEW.fingerprint) IS DISTINCT FROM (OLD.id,OLD.consumer_id,OLD.fingerprint) OR (OLD.retired AND NOT NEW.retired)
   THEN RAISE EXCEPTION 'immutable window identity'; END IF;
 ELSE
   PERFORM id FROM auth_binding.consumer WHERE id=NEW.consumer_id FOR UPDATE;
   IF (SELECT count(*) FROM auth_binding.window_key WHERE consumer_id=NEW.consumer_id AND NOT retired)>=2
   THEN RAISE EXCEPTION 'window identity limit'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER window_guard BEFORE INSERT OR UPDATE ON auth_binding.window_key FOR EACH ROW EXECUTE FUNCTION auth_binding.window_guard();
REVOKE ALL ON SCHEMA auth_binding,ba_fixture FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA auth_binding,ba_fixture FROM PUBLIC;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auth_binding FROM PUBLIC;
ALTER TABLE auth_binding.enrollment ADD UNIQUE(id,account_id);
ALTER TABLE auth_binding.host_authorization ADD FOREIGN KEY(enrollment_id,account_id) REFERENCES auth_binding.enrollment(id,account_id);
CREATE FUNCTION auth_binding.immutable_host_authorization() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (NEW.id,NEW.enrollment_id,NEW.account_id,NEW.epoch) IS DISTINCT FROM (OLD.id,OLD.enrollment_id,OLD.account_id,OLD.epoch)
 OR (OLD.revoked AND NOT NEW.revoked) THEN RAISE EXCEPTION 'immutable host authorization'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable_host_authorization BEFORE UPDATE ON auth_binding.host_authorization FOR EACH ROW EXECUTE FUNCTION auth_binding.immutable_host_authorization();
CREATE FUNCTION auth_binding.immutable_policy() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF (NEW.account_id,NEW.remote_account_id) IS DISTINCT FROM (OLD.account_id,OLD.remote_account_id) OR NEW.epoch<OLD.epoch
 THEN RAISE EXCEPTION 'immutable remote account mapping or epoch rollback'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER immutable_policy BEFORE UPDATE ON auth_binding.policy FOR EACH ROW EXECUTE FUNCTION auth_binding.immutable_policy();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auth_binding FROM PUBLIC;
